__modules["core.db"] = function()
local storage = require("ttt.storage")
local U = require("core.util")
local S = require("core.state")
local Psql = require("core.psql")
local SQL = require("core.sql")

local Db = {}

local KINDS = { r = "table", p = "table", f = "table", v = "view", m = "view" }

local function pick_schema()
  for _, name in ipairs(S.schemas) do
    if name == S.schema then
      return
    end
  end
  S.schema = "public"
  for _, name in ipairs(S.schemas) do
    if name == "public" then
      return
    end
  end
  S.schema = S.schemas[1] or "public"
end

local function relations_loaded(gen, err, sets)
  if gen ~= S.relations_gen then
    return
  end
  S.relations_loading = false
  S.relations_err = err
  local list = {}
  for _, r in ipairs(not err and sets[1] and sets[1].rows or {}) do
    list[#list + 1] = { name = r[1], relkind = r[2], kind = KINDS[r[2]] or "table", estimate = tonumber(r[3]) }
  end
  S.relations = list
  S.redraw()
end

function Db.load_relations()
  if S.status ~= "ok" then
    return
  end
  S.relations_gen = S.relations_gen + 1
  S.relations_loading = true
  S.relations_err = nil
  S.redraw()
  Psql.query(SQL.relations(S.schema), U.bind(relations_loaded, S.relations_gen))
end

function Db.set_schema(name)
  if name == S.schema then
    return
  end
  S.schema = name
  S.relations = {}
  storage.set("schema", name)
  Db.load_relations()
end

local function connected(gen, cb, err, sets)
  if gen ~= S.gen then
    return
  end
  if err then
    S.status = "error"
    S.message = err
  else
    local info = sets[1] and sets[1].rows[1] or {}
    S.status = "ok"
    S.message = ""
    S.server = { user = info[1], database = info[2], host = info[3], port = info[4], version = info[5] }
    S.schemas = {}
    for _, r in ipairs(sets[2] and sets[2].rows or {}) do
      S.schemas[#S.schemas + 1] = r[1]
    end
    pick_schema()
    Db.load_relations()
  end
  S.redraw()
  if cb then
    cb(err)
  end
end

function Db.connect(cb)
  S.gen = S.gen + 1
  S.status = "connecting"
  S.message = ""
  S.redraw()
  Psql.query(SQL.CONNECT, U.bind(connected, S.gen, cb))
end

function Db.ensure_connected()
  if S.status == "idle" and S.configured() then
    Db.connect()
  end
end

function Db.refresh()
  if S.status == "ok" then
    Db.load_relations()
  else
    Db.connect()
  end
end

-- What the status line calls the server.
function Db.label()
  local c = S.conn
  local uri = U.trim(c.uri)
  if S.server then
    local host = uri ~= "" and uri:match("@([^/?]+)") or (uri == "" and c.host .. ":" .. c.port) or nil
    if not host then
      host = S.server.host .. (S.server.port ~= "" and ":" .. S.server.port or "")
    end
    return S.server.user .. "@" .. host .. "/" .. S.server.database
  end
  if uri ~= "" then
    local uri = U.trim(c.uri):gsub("://([^:@/]*):[^@]*@", "://%1@")
    return (uri:gsub("password=%S+", "password=…"))
  end
  return c.user .. "@" .. c.host .. ":" .. c.port .. "/" .. c.database
end

return Db
end

-- src/core/parse.lua --------------------------------------------------------
__modules["core.parse"] = function()
local U = require("core.util")

-- Reads psql's output (see core.psql) as it streams in. Chunks may split it
-- anywhere, so whatever follows the last complete record or line is carried
-- over to the next chunk. Each result set keeps its first max_rows rows and
-- counts the rest.
local M = {}

M.US = "\31"
M.RS = "\30"

local MARKER = "^ttt%-postgres backend (%d+) ([%d%.]+)$"
local FOOTER = "^%((%d+) rows?%)\n"
-- Longer than any "(N rows)\n" footer.
local SHORT = 32

function M.new(max_rows)
  return {
    max_rows = max_rows or math.huge,
    statements = {},
    cur = nil,
    set = nil,
    carry = {},
    carry_len = 0,
    received = 0,
    backend = nil,
  }
end

local function current(p)
  if not p.cur then
    p.cur = {}
    p.statements[#p.statements + 1] = p.cur
  end
  return p.cur
end

local function timing(line)
  local ms = line:match("^[^:]+: ([%d%.,]+) ms")
  if ms then
    return tonumber((ms:gsub(",", ".")))
  end
end

local function on_line(p, line)
  if not p.backend then
    local pid, started = line:match(MARKER)
    if pid then
      p.backend = { pid = tonumber(pid), started = started }
      return
    end
  end
  local ms = timing(line)
  if ms then
    current(p).ms = ms
    p.cur = nil
  elseif line ~= "" then
    current(p).tag = line
  end
end

local function on_header(p, header)
  local st = current(p)
  if st.result then
    p.cur = nil
    st = current(p)
  end
  st.result = { columns = U.split(header, M.US), rows = {}, total = 0, complete = false }
  p.set = st.result
end

local function on_row(p, s, i, j)
  local set = p.set
  set.total = set.total + 1
  p.received = p.received + 1
  if set.total <= p.max_rows then
    set.rows[set.total] = U.split(s:sub(i, j), M.US)
  end
end

-- The footer is told apart from a row that happens to look like one by its
-- count, which matches the rows read so far.
local function footer_end(p, s, pos)
  if s:byte(pos) ~= 40 then
    return nil
  end
  local _, fe, n = s:sub(pos, pos + SHORT):find(FOOTER)
  if fe and tonumber(n) == p.set.total then
    return pos + fe - 1
  end
end

local function consume(p, s)
  local pos, n = 1, #s
  while pos <= n do
    if p.set then
      local fe = footer_end(p, s, pos)
      if fe then
        p.set.complete = true
        p.set = nil
        pos = fe + 1
      else
        local rs = s:find(M.RS, pos, true)
        if not rs then
          break
        end
        on_row(p, s, pos, rs - 1)
        pos = rs + 1
      end
    else
      local at = s:find("[\30\n]", pos)
      if not at then
        break
      end
      if s:byte(at) == 10 then
        on_line(p, s:sub(pos, at - 1))
      else
        on_header(p, s:sub(pos, at - 1))
      end
      pos = at + 1
    end
  end
  return s:sub(pos)
end

local function completes(p, chunk)
  if p.set then
    return chunk:find(M.RS, 1, true) or (p.carry_len < SHORT and chunk:find("\n", 1, true))
  end
  return chunk:find("[\30\n]")
end

function M.feed(p, chunk)
  if chunk == "" then
    return
  end
  if p.carry_len > 0 then
    local done = completes(p, chunk)
    p.carry[#p.carry + 1] = chunk
    p.carry_len = p.carry_len + #chunk
    if not done then
      return
    end
    chunk = table.concat(p.carry)
  end
  local rest = consume(p, chunk)
  p.carry = { rest }
  p.carry_len = #rest
end

-- An unfinished result set keeps complete = false; its last, partial record
-- is dropped.
function M.finish(p)
  local rest = table.concat(p.carry)
  p.carry, p.carry_len = {}, 0
  if p.set then
    if footer_end(p, rest .. "\n", 1) then
      p.set.complete = true
    end
    p.set = nil
  elseif rest ~= "" then
    on_line(p, rest)
  end
  return p.statements
end

return M
end

-- src/core/psql.lua ---------------------------------------------------------
__modules["core.psql"] = function()
local sys = require("ttt.system")
local U = require("core.util")
local S = require("core.state")
local Saved = require("core.saved")
local Parse = require("core.parse")

-- psql runs unaligned with the ASCII unit and record separators between
-- fields and rows, and a control character for NULL, so values with commas,
-- quotes, tabs or newlines need no unquoting. The footer stays on: a result
-- set always ends in "<RS>(N rows)\n", which tells it apart from a command
-- tag such as "UPDATE 3".
local M = {}

M.US = Parse.US
M.RS = Parse.RS
M.NULL = "\29"

local function quote(v)
  local s = tostring(v):gsub("\\", "\\\\"):gsub("'", "\\'")
  return "'" .. s .. "'"
end

local function add(parts, key, value)
  value = U.trim(value)
  if value ~= "" then
    parts[#parts + 1] = key .. "=" .. quote(value)
  end
end

-- The password never goes into the connection string: psql gets it through
-- PGPASSWORD, which other users cannot read in the process list.
function M.target(conn)
  local uri, uri_password = Saved.split_uri(conn.uri)
  local password = (conn.password or "") ~= "" and conn.password or uri_password or ""
  if uri ~= "" then
    return uri, password
  end
  local parts = {}
  add(parts, "host", conn.host)
  add(parts, "port", conn.port)
  add(parts, "dbname", conn.database)
  add(parts, "user", conn.user)
  add(parts, "connect_timeout", "10")
  add(parts, "application_name", "ttt-postgres")
  return table.concat(parts, " "), password
end

function M.args(conninfo)
  return {
    "-X",
    "-q",
    "-w",
    "-v",
    "ON_ERROR_STOP=1",
    "-A",
    "-F",
    M.US,
    "-R",
    M.RS,
    "-P",
    "footer=on",
    "-P",
    "null=" .. M.NULL,
    "-d",
    conninfo,
  }
end

local function clean_error(text)
  local out = {}
  for _, line in ipairs(U.lines(text)) do
    line = line:gsub("^psql:[^:]*:%d+: ", "")
    line = line:gsub("^psql: error: ", "")
    out[#out + 1] = line
  end
  return table.concat(out, "\n")
end

function M.error_text(res)
  local stderr = U.trim(res.stderr)
  if res.exit_code == -1 then
    if stderr:find("not found", 1, true) or stderr:find("no such file", 1, true) then
      return "psql was not found ("
        .. S.psql_path
        .. "). Install the PostgreSQL client or set its path in Postgres: Settings…"
    end
    return stderr ~= "" and stderr or "psql could not be started"
  end
  if stderr == "" then
    return "psql exited with code " .. tostring(res.exit_code)
  end
  return clean_error(stderr)
end

M.OUTPUT_LIMIT = 64 * 1024 * 1024
M.OUTPUT_LIMIT_LABEL = "64 MiB"
M.CATALOG_TIMEOUT_MS = 30000

-- Killing psql leaves its statement running on the server, so a cancel or a
-- timeout also cancels the backend. Its start time guards against a reused
-- pid.
local PRELUDE = "select pg_backend_pid() as ttt_pid, coalesce((select extract(epoch from backend_start)::text"
  .. " from pg_stat_activity where pid = pg_backend_pid()), '0') as ttt_started \\gset\n"
  .. "\\echo ttt-postgres backend :ttt_pid :ttt_started\n"

local CANCEL = "select pg_cancel_backend(pid) from pg_stat_activity"
  .. " where pid = %d and extract(epoch from backend_start)::text = %s;\n"

local function ignore() end

local function cancel_backend(run)
  local b = run.parser.backend
  if not b then
    return
  end
  local opts = { stdin = string.format(CANCEL, b.pid, U.literal(b.started)), timeout_ms = 10000 }
  if run.password ~= "" then
    opts.env = { PGPASSWORD = run.password }
  end
  sys.exec_async(run.path, M.args(run.conninfo), opts, ignore)
end

local function stdout(run, chunk)
  Parse.feed(run.parser, chunk)
  if run.on_progress then
    run.on_progress(run.parser.received)
  end
end

local function finished(run, cb, res)
  local out = {
    stderr = res.stderr or "",
    code = res.exit_code,
    statements = Parse.finish(run.parser),
    elapsed = os.clock() - run.started,
  }
  if res.cancelled then
    out.stopped = "cancelled"
  elseif res.timed_out then
    out.stopped = "timed_out"
  elseif res.truncated then
    out.stopped = "truncated"
  elseif res.exit_code ~= 0 then
    out.err = M.error_text(res)
  end
  if out.stopped then
    cancel_backend(run)
  end
  cb(out)
end

local function exec_error(path, err)
  local msg = tostring(err)
  if not msg:find("permission denied", 1, true) then
    return msg
  end
  if path ~= "psql" then
    return path .. " is not approved. Save it in Postgres: Settings… to approve it."
  end
  return msg .. ". Approve the plugin's system.exec permission for psql."
end

-- Runs a script on psql's standard input, so neither the SQL nor its length
-- reaches the command line. opts: timeout_ms, max_rows (kept per result set)
-- and on_progress(rows_received). cb(out) gets { statements, stderr, err,
-- stopped = "cancelled"|"timed_out"|"truncated", elapsed }. Returns a handle
-- for M.cancel, or nil when psql could not start.
function M.run(script, opts, cb)
  if not sys.exec_async then
    cb({ err = "The plugin needs the system.exec permission for psql.", statements = {} })
    return nil
  end
  local conninfo, password = M.target(S.conn)
  local run = {
    parser = Parse.new(opts.max_rows),
    path = S.psql_path,
    conninfo = conninfo,
    password = password,
    on_progress = opts.on_progress,
    started = os.clock(),
  }
  local exec_opts = {
    stdin = PRELUDE .. script,
    timeout_ms = opts.timeout_ms,
    max_output_bytes = M.OUTPUT_LIMIT,
    on_stdout = U.bind(stdout, run),
  }
  if password ~= "" then
    exec_opts.env = { PGPASSWORD = password }
  end
  local handle, err = sys.exec_async(run.path, M.args(conninfo), exec_opts, U.bind(finished, run, cb))
  if not handle then
    cb({ err = exec_error(run.path, err), statements = {} })
    return nil
  end
  run.handle = handle
  return run
end

function M.cancel(run)
  if run and run.handle then
    run.handle:cancel()
  end
end

function M.stopped_text(out, timeout_ms)
  if out.stopped == "timed_out" then
    return "No result after " .. U.duration(timeout_ms / 1000) .. ", so psql was stopped."
  elseif out.stopped == "truncated" then
    return "psql's output passed " .. M.OUTPUT_LIMIT_LABEL .. ", so it was stopped."
  end
  return "Cancelled."
end

local function results(cb, timeout_ms, out)
  if out.stopped then
    return cb(M.stopped_text(out, timeout_ms))
  end
  if out.err then
    return cb(out.err)
  end
  local list = {}
  for _, st in ipairs(out.statements) do
    if st.result then
      list[#list + 1] = st.result
    end
  end
  cb(nil, list)
end

-- For the plugin's own queries: cb(err, result_sets). opts.timeout_ms
-- replaces the catalog timeout; nil there means none.
function M.query(sql, cb, opts)
  local timeout = M.CATALOG_TIMEOUT_MS
  if opts then
    timeout = opts.timeout_ms
  end
  M.run(sql, { timeout_ms = timeout }, U.bind(results, cb, timeout))
end

function M.is_null(v)
  return v == M.NULL
end

return M
end

