__modules["features.query"] = function()
local ttt = require("ttt")
local U = require("core.util")
local S = require("core.state")
local Router = require("app.router")
local Store = require("features.query.store")
local Page = require("features.query.page")

local M = {}

function M.new(sql, run)
  local q = Store.new(sql)
  Router.show("query:" .. q.id, U.bind(Page.page, q), true)
  if run then
    Store.run(q)
  end
  return q
end

function M.open_with(sql)
  M.new(sql, true)
end

function M.run_active()
  if S.active_query then
    Store.run(S.active_query)
  else
    ttt.notify("Open a query tab first: Postgres: New Query", "warn")
  end
end

return M
end

-- src/features/query/page.lua -----------------------------------------------
__modules["features.query.page"] = function()
local U = require("core.util")
local S = require("core.state")
local UI = require("components")
local Store = require("features.query.store")

local M = {}

local function set_sql(q, text)
  q.sql = text
end

local function status_text(q)
  if q.running then
    local text = "Running…"
    if q.received > 0 then
      text = text .. " " .. U.plural(q.received, "row") .. " so far"
    end
    return text, "muted"
  end
  if q.stopped == "cancelled" then
    return "■ Cancelled · " .. q.summary, "warning"
  end
  if q.stopped == "timed_out" then
    return "✕ Timed out · " .. q.summary, "danger"
  end
  if q.err and q.ran then
    return "✕ Failed · " .. q.summary, "danger"
  end
  if q.ran then
    return "✓ " .. q.summary, q.shown and "warning" or "success"
  end
  return "F5 runs the SQL above. Enter on a result row shows it in full.", "muted"
end

local function toolbar(q, h)
  h:button({ label = "Run", on_click = U.bind(Store.run, q) })
  if q.running then
    h:button({ label = "Cancel", style = "muted", on_click = U.bind(Store.cancel, q) })
  end
  local text, style = status_text(q)
  h:label({ text = text, style = style })
end

local function results(q, p)
  if q.err then
    UI.error_box(p, q.stopped == "timed_out" and "Timed out" or "Error", q.err)
  end
  if q.notices then
    UI.error_box(p, "Notices", q.notices)
  end
  if q.result and #q.result.columns > 0 then
    if q.shown then
      p:label({ text = q.shown, style = "warning", padding_left = 1, margin_top = 1 })
    end
    UI.grid.render(p, q.grid, { title = q.title, empty = "The query returned no rows" })
  end
end

local function render(q, p)
  S.active_query = q
  p:input({
    border = true,
    title = "SQL",
    value = q.sql,
    placeholder = "select * from …",
    multiline = true,
    min_rows = 8,
    max_rows = 8,
    autofocus = true,
    margin_top = 1,
    on_change = U.bind(set_sql, q),
  })
  UI.toolbar(p, U.bind(toolbar, q), 0)
  results(q, p)
end

local function on_event(q, ev)
  if ev.type == "key" and ev.key == "F5" then
    Store.run(q)
    return true
  end
end

local function forget(q)
  Store.abandon(q)
  if S.active_query == q then
    S.active_query = nil
  end
end

function M.page(q)
  return {
    title = q.title,
    render = U.bind(render, q),
    on_event = U.bind(on_event, q),
    on_close = U.bind(forget, q),
  }
end

return M
end

