__modules["features.table"] = function()
local U = require("core.util")
local Router = require("app.router")
local Store = require("features.table.store")
local Page = require("features.table.page")

local M = {}

M.store = Store
M.page = Page

-- Opens a table or view in its own tab, or focuses it when it is open.
function M.open(schema, name, kind)
  local rel = Store.relation(schema, name, kind)
  Router.show("table:" .. rel.key, U.bind(Page.page, rel))
end

return M
end

-- src/features/table/page.lua -----------------------------------------------
__modules["features.table.page"] = function()
local U = require("core.util")
local S = require("core.state")
local UI = require("components")
local Router = require("app.router")
local Store = require("features.table.store")
local Structure = require("features.table.structure_tab")

local M = {}

local TABS = { { id = "data", label = "Data" }, { id = "structure", label = "Structure" } }

M.open_query = nil

local function data_tab(p, rel)
  local grid = rel.data
  if not grid.loaded and not grid.loading then
    Store.load_data(rel, 0)
  end
  if grid.err then
    UI.error_box(p, "Couldn't load rows", grid.err)
    return
  end
  UI.grid.render(p, grid, { title = rel.key, empty = "No rows in " .. rel.name })
end

local function refresh(page, rel)
  if page.tab == "structure" then
    Store.load_structure(rel)
  else
    Store.load_data(rel)
  end
end

local function query(rel)
  if M.open_query then
    M.open_query("select *\nfrom " .. U.qualified(rel.schema, rel.name) .. "\nlimit 100;")
  end
end

local function actions(page, rel, h)
  h:button({ label = "Refresh", on_click = U.bind(refresh, page, rel) })
  h:button({ label = "Query", on_click = U.bind(query, rel) })
end

local function render(page, rel, p)
  S.active_query = nil
  local current = Router.tab_strip(p, page, TABS)
  if current == "structure" then
    Structure.render(p, rel)
  else
    data_tab(p, rel)
  end
end

function M.page(rel)
  local page = { title = rel.key, tab_title = rel.name, on_close = U.bind(Store.forget, rel.key) }
  page.actions = U.bind(actions, page, rel)
  page.render = U.bind(render, page, rel)
  return page
end

return M
end

-- src/features/table/store.lua ----------------------------------------------
__modules["features.table.store"] = function()
local U = require("core.util")
local S = require("core.state")
local Psql = require("core.psql")
local SQL = require("core.sql")
local UI = require("components")

local M = {}

M.relations = {}

function M.key(schema, name)
  return schema .. "." .. name
end

local function data_loaded(rel, gen, err, sets)
  local grid = rel.data
  if gen ~= grid.gen then
    return
  end
  grid.loading = false
  grid.loaded = true
  grid.err = err
  if err then
    grid.rows = {}
  else
    local count, page = sets[1], sets[2]
    grid.total = tonumber(count and count.rows[1] and count.rows[1][1]) or 0
    grid.columns = page and page.columns or {}
    grid.rows = page and page.rows or {}
    if grid.sel > #grid.rows then
      grid.sel = math.max(#grid.rows, 1)
    end
  end
  S.redraw()
end

function M.load_data(rel, offset)
  local grid = rel.data
  grid.offset = offset or grid.offset
  grid.gen = grid.gen + 1
  grid.loading = true
  S.redraw()
  Psql.query(
    SQL.page(rel.schema, rel.name, S.page_size, grid.offset),
    U.bind(data_loaded, rel, grid.gen),
    { timeout_ms = S.query_timeout_ms() }
  )
end

local function rows_of(set)
  return set and set.rows or {}
end

local function structure_loaded(rel, gen, err, sets)
  local st = rel.structure
  if gen ~= st.gen then
    return
  end
  st.loading = false
  st.loaded = true
  st.err = err
  if not err then
    local info = rows_of(sets[1])[1] or {}
    st.info = { relkind = info[1], size = info[2], estimate = tonumber(info[3]), comment = info[4], viewdef = info[5] }
    st.columns = rows_of(sets[2])
    st.constraints = rows_of(sets[3])
    st.indexes = rows_of(sets[4])
    st.referenced_by = rows_of(sets[5])
  end
  S.redraw()
end

function M.load_structure(rel)
  local st = rel.structure
  st.gen = st.gen + 1
  st.loading = true
  S.redraw()
  Psql.query(SQL.structure(rel.schema, rel.name), U.bind(structure_loaded, rel, st.gen))
end

function M.relation(schema, name, kind)
  local key = M.key(schema, name)
  local rel = M.relations[key]
  if not rel then
    rel = {
      key = key,
      schema = schema,
      name = name,
      kind = kind or "table",
      data = UI.grid.new({ gen = 0 }),
      structure = { gen = 0, loaded = false, loading = false },
    }
    rel.data.on_page = U.bind(M.load_data, rel)
    M.relations[key] = rel
  end
  return rel
end

function M.forget(key)
  M.relations[key] = nil
end

function M.reload_all()
  for _, rel in pairs(M.relations) do
    rel.data.offset = 0
    rel.data.loaded = false
    rel.structure.loaded = false
  end
end

return M
end

-- src/features/table/structure_tab.lua --------------------------------------
__modules["features.table.structure_tab"] = function()
local U = require("core.util")
local UI = require("components")
local Store = require("features.table.store")

local M = {}

local KIND = { r = "Table", p = "Partitioned table", f = "Foreign table", v = "View", m = "Materialized view" }
local CONTYPE = { p = "primary key", f = "foreign key", u = "unique", c = "check", x = "exclusion", t = "trigger" }

local COLUMN_COLUMNS = {
  { label = "#", width = 3, align = "right" },
  { label = "Name" },
  { label = "Type" },
  { label = "Null", width = 8 },
  { label = "Default" },
  { label = "Key", width = 6 },
}

local INDEX_COLUMNS = {
  { label = "Name" },
  { label = "Kind", width = 8 },
  { label = "Size", width = 10, align = "right" },
  { label = "Definition" },
}

local FK_COLUMNS = { { label = "Name" }, { label = "Definition" } }
local REF_COLUMNS = { { label = "Table" }, { label = "Name" }, { label = "Definition" } }
local CONSTRAINT_COLUMNS = { { label = "Name" }, { label = "Type", width = 10 }, { label = "Definition" } }

local function section_table(columns, rows, empty, b)
  local fitted, cells = UI.grid.fit(columns, rows)
  b:table({ inset = 1, columns = fitted, rows = cells, empty = empty })
end

local function section(p, title, columns, rows, empty)
  UI.frame(
    p,
    title .. "  " .. tostring(#rows),
    U.bind(section_table, columns, rows, empty),
    { height = math.max(#rows, 1) + 5, margin_top = 1 }
  )
end

local function definition_lines(lines, b)
  for _, line in ipairs(lines) do
    b:label({ text = line, style = "code", padding_left = 1 })
  end
end

local function view_definition(p, text)
  local lines = U.split(U.trim(text), "\n")
  UI.frame(p, "Definition", U.bind(definition_lines, lines), { height = #lines + 3, margin_top = 1 })
end

local function split_constraints(st)
  local pk, fks, others = nil, {}, {}
  for _, c in ipairs(st.constraints or {}) do
    if c[2] == "p" then
      pk = c[3]
    elseif c[2] == "f" then
      fks[#fks + 1] = { c[1], c[3] }
    else
      others[#others + 1] = { c[1], CONTYPE[c[2]] or c[2], c[3] }
    end
  end
  return pk, fks, others
end

local function column_rows(st)
  local rows = {}
  for i, c in ipairs(st.columns or {}) do
    rows[i] = { tostring(i), c[1], c[2], c[3], UI.grid.cell(c[4]), c[5] }
  end
  return rows
end

local function index_rows(st)
  local rows = {}
  for i, ix in ipairs(st.indexes or {}) do
    rows[i] = { ix[1], ix[3], ix[4], ix[2] }
  end
  return rows
end

local function ref_rows(st)
  local rows = {}
  for i, r in ipairs(st.referenced_by or {}) do
    rows[i] = { r[1], r[2], r[3] }
  end
  return rows
end

local function body(rel, sv)
  local st = rel.structure
  local info = st.info or {}
  local pk, fks, others = split_constraints(st)
  local is_view = info.relkind == "v" or info.relkind == "m"
  local estimate = info.estimate and info.estimate >= 0 and U.count(info.estimate) or "not analyzed"
  local kv = { { "Kind", KIND[info.relkind] or info.relkind } }
  if info.relkind ~= "v" then
    kv[#kv + 1] = { "Estimated rows", estimate }
    kv[#kv + 1] = { "Total size", info.size }
  end
  if not is_view then
    kv[#kv + 1] = { "Primary key", pk or "none" }
  end
  if info.comment and info.comment ~= "" then
    kv[#kv + 1] = { "Comment", info.comment }
  end
  sv:keyvalue(UI.kv(kv))
  section(sv, "Columns", COLUMN_COLUMNS, column_rows(st), "No columns")
  if is_view and info.viewdef ~= "" then
    view_definition(sv, info.viewdef)
  end
  if info.relkind ~= "v" then
    section(sv, "Indexes", INDEX_COLUMNS, index_rows(st), "No indexes")
  end
  if not is_view then
    section(sv, "Foreign keys", FK_COLUMNS, fks, "No foreign keys")
    section(sv, "Referenced by", REF_COLUMNS, ref_rows(st), "No foreign keys point here")
    section(sv, "Other constraints", CONSTRAINT_COLUMNS, others, "No unique, check or exclusion constraints")
  end
end

function M.render(p, rel)
  local st = rel.structure
  if not st.loaded and not st.loading then
    Store.load_structure(rel)
  end
  if st.err then
    UI.error_box(p, "Couldn't load the structure", st.err)
    return
  end
  if not st.loaded then
    UI.status(p, "Loading…")
    return
  end
  p:scrollview({ render = U.bind(body, rel) })
end

return M
end

